import logging
from azure.core.credentials import AzureKeyCredential
from azure.monitor import monitoringv1
from azure.monitor.models import SemanticEvent

SUBSCRIPTION_ID = "<your-subscription-id>"
LOG_ANALYTICS_WORKSPACE_ID = "<your-log-analytics-workspace-id>"
LOG_ANALYTICS_WORKSPACE_KEY = "<your-log-analytics-workspace-key>"

client = monitoringv1.LogAnalyticsClient(
    subscription_id=SUBSCRIPTION_ID,
    credential=AzureKeyCredential(LOG_ANALYTICS_WORKSPACE_KEY)
)

def log_event(request_id: str, message: str) -> None:
    log_event_data = SemanticEvent(
        properties={
            "RequestID": request_id,
            "Message": message
        }
    )

    client.create_log_analytics_schema(namespace="MyApp")    
    client.create_log_analytics_property(
        namespace="MyApp",
        property_name="RequestID",
        property_type="string"
    )
    client.create_log_analytics_property(
        namespace="MyApp",
        property_name="Message",
        property_type="string"
    )      
    client.log_struct(namespace="MyApp", data=log_event_data)
